const crypto = require('crypto');
const secret = $env.STRIPE_WEBHOOK_SECRET || 'PLACEHOLDER_STRIPE_WEBHOOK_SECRET';
const sigHeader = $input.first().json.headers['stripe-signature'] || '';
const rawBody = $input.first().json.body /* ASSUMES this is the raw string, per the rawBody option on the Stripe webhook node - not verified */;

const parts = Object.fromEntries(sigHeader.split(',').map((kv) => kv.split('=')));
const signedPayload = `${parts.t}.${rawBody}`;
const expected = crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');

let valid = false;
try {
  valid = crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(parts.v1 || '', 'hex'));
} catch (e) {
  valid = false; // length mismatch etc. - definitely not a valid signature
}

const event = valid ? JSON.parse(rawBody) : null;
const RELEVANT_TYPES = ['checkout.session.completed', 'payment_intent.succeeded'];

return [{
  json: {
    ok: valid,
    handled: valid && RELEVANT_TYPES.includes(event?.type),
    eventType: event?.type,
    opportunityId: event?.data?.object?.metadata?.opportunityId,
  },
}];
